cd /tmp && cat > hello.c <<'EOF'
#include <stdio.h>
int add(int a, int b){ return a + b; }
int main(void){ printf("result=%d\n", add(40, 2)); return 0; }
EOF
/tmp/CompCert/ccomp -S hello.c -o hello.s 2>&1; echo "COMPILE_EXIT=$?"; ls -la hello.s 2>&1

cd /tmp && cat > rich.c <<'EOF'
#include <stdio.h>
struct point { int x; int y; };
int fib(int n){ if(n<2) return n; return fib(n-1)+fib(n-2); }
int main(void){
    struct point p = {3,4};
    int a[5] = {1,2,3,4,5};
    int *q = a;
    int s = 0;
    for(int i=0;i<5;i++) s += q[i];
    float f = 3.5f + 2.25f;
    printf("fib10=%d sum=%d pt=%d f=%.2f\n", fib(10), s, p.x+p.y, f);
    return 0;
}
EOF
/tmp/CompCert/ccomp -c rich.c -o rich.o 2>&1; echo "CC=$?"; gcc rich.o -o rich 2>/dev/null; echo "LINK=$?"; ./rich; echo "RUN=$?"

